// s5_expr.js - Expression evaluator with + - * / operations

function evaluate(expr) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }

    // Check for invalid characters - allow numbers, +, -, *, /, ., (, )
    // But we need to be more careful about minus signs
    if (!/^[0-9+\-*/.()]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Handle division by zero
    if (expr.match(/\/0(?:\.0*)?/)) {
        throw new Error('Division by zero');
    }

    // Simple evaluation using Function constructor
    try {
        // The Function constructor should handle parentheses and unary minus correctly
        const result = new Function('return ' + expr)();

        if (typeof result !== 'number' || isNaN(result)) {
            throw new Error('Invalid expression');
        }

        return result;
    } catch (e) {
        throw new Error('Invalid expression');
    }
}

